"use strict";
import { useQuery } from "@tanstack/react-query";
const ABSTRACT_SUBGRAPH_URLS = {
  [11124]: {
    // Abstract Testnet
    v2: "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api",
    v3: "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api"
  },
  [2741]: {
    // Abstract Mainnet
    v2: "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api",
    // Use testnet for now
    v3: "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api"
    // Use testnet for now
  }
};
const V2_ALL_POOLS_QUERY = `
  query GetAllV2Pools($first: Int!, $skip: Int!) {
    pairs(
      first: $first
      skip: $skip
      orderBy: reserveUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
      volumeUSD
      txCount
    }
  }
`;
const V3_ALL_POOLS_QUERY = `
  query GetAllV3Pools($first: Int!, $skip: Int!) {
    pools(
      first: $first
      skip: $skip
      orderBy: totalValueLockedUSD
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
      volumeUSD
      txCount
      feesUSD
    }
  }
`;
const TICK_SPACING_TO_FEE = {
  1: 100,
  // 0.01%
  50: 500,
  // 0.05%
  100: 500,
  // 0.05%
  200: 3e3,
  // 0.3%
  2e3: 1e4
  // 1%
};
function getV3PoolType(tickSpacing) {
  const spacing = parseInt(tickSpacing);
  const fee = TICK_SPACING_TO_FEE[spacing];
  if (fee) {
    return `Concentrated Volatile ${spacing}`;
  }
  return `Concentrated Volatile ${spacing}`;
}
async function fetchPoolsFromSubgraph(url, query, variables) {
  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        query,
        variables
      })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Subgraph errors:", data.errors);
      return [];
    }
    return data.data?.pairs || data.data?.pools || [];
  } catch (error) {
    console.error("Failed to fetch from subgraph:", error);
    return [];
  }
}
export function useAbstractLiquidityPools(chainId = 11124, enabled = true) {
  const { data, isLoading, isError, error } = useQuery({
    queryKey: ["abstractLiquidityPools", chainId],
    queryFn: async () => {
      const urls = ABSTRACT_SUBGRAPH_URLS[chainId];
      if (!urls) {
        throw new Error(`No subgraph URLs configured for chain ${chainId}`);
      }
      const [v2Pools, v3Pools] = await Promise.all([
        fetchPoolsFromSubgraph(urls.v2, V2_ALL_POOLS_QUERY, { first: 100, skip: 0 }),
        fetchPoolsFromSubgraph(urls.v3, V3_ALL_POOLS_QUERY, { first: 100, skip: 0 })
      ]);
      const transformedV2Pools = v2Pools.map((pool) => ({
        ...pool,
        protocol: "V2",
        type: pool.stable ? "Stable" : "Volatile"
      }));
      const transformedV3Pools = v3Pools.map((pool) => ({
        ...pool,
        protocol: "V3",
        type: "Concentrated",
        tickSpacingNumber: parseInt(pool.tickSpacing || "200")
      }));
      const allPools = [
        ...transformedV2Pools,
        ...transformedV3Pools
      ];
      allPools.sort((a, b) => {
        const aValue = parseFloat(
          a.protocol === "V3" ? a.totalValueLockedUSD || "0" : a.reserveUSD || "0"
        );
        const bValue = parseFloat(
          b.protocol === "V3" ? b.totalValueLockedUSD || "0" : b.reserveUSD || "0"
        );
        return bValue - aValue;
      });
      return allPools;
    },
    enabled,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    retry: 2
  });
  return {
    pools: data || [],
    isLoading,
    isError,
    error
  };
}
export function calculatePoolAPR(pool) {
  if (pool.protocol === "V2") {
    return pool.type === "Stable" ? 0.05 : 0.3;
  } else {
    const tickSpacing = pool.tickSpacingNumber;
    const feeMap = {
      1: 0.01,
      // 0.01%
      50: 0.05,
      // 0.05%
      100: 0.05,
      // 0.05%
      200: 0.3,
      // 0.3%
      2e3: 1
      // 1%
    };
    return feeMap[tickSpacing] || 0.3;
  }
}
export function formatPoolDisplayName(pool) {
  const token0Symbol = pool.token0.symbol;
  const token1Symbol = pool.token1.symbol;
  if (pool.protocol === "V2") {
    return `${token0Symbol}/${token1Symbol}`;
  } else {
    const v3Pool = pool;
    return `${token0Symbol}/${token1Symbol}`;
  }
}
export function getPoolTypeDisplay(pool) {
  if (pool.protocol === "V2") {
    return pool.type === "Stable" ? "Basic Stable" : "Basic Volatile";
  } else {
    return "Concentrated Volatile";
  }
}
